153	/**
154	 * Assess test scenarios and auto-assign priority based on risk score
155	 */
156	export function assessTestScenarios(scenarios: Omit<TestScenario, 'risk' | 'priority'>[]): TestScenario[] {
157	  return scenarios.map((scenario) => {
158	    // Auto-assign priority based on risk score
159	    const priority = mapRiskToPriority(scenario.risk.score);
160	    return { ...scenario, priority };
161	  });
162	}
163	
164	/**
165	 * Map risk score to test priority (P0-P3)
166	 * P0: Critical (score 9) - blocks release
167	 * P1: High (score 6-8) - must fix before release
168	 * P2: Medium (score 4-5) - fix if time permits
169	 * P3: Low (score 1-3) - document and defer
