212	      impact: 1, // Minor (cosmetic issue, email still sent)
213	      reasoning: 'Non-blocking, users get email regardless',
214	    }),
215	    testLevel: 'Unit',
216	    owner: 'dev-team',
217	  },
218	  {
219	    id: 'PAY-004',
220	    title: 'Payment fails gracefully when Stripe is down',
221	    feature: 'Checkout',
222	    risk: assessRisk({
223	      probability: 1, // Unlikely (Stripe has 99.99% uptime)
224	      impact: 3, // Critical (complete checkout failure)
225	      reasoning: 'Rare but catastrophic, requires retry mechanism',
226	    }),
