231	
232	/**
233	 * Generate risk assessment report with priority distribution
234	 */
235	export function generateRiskReport(scenarios: TestScenario[]): string {
236	  const priorityCounts = scenarios.reduce(
237	    (acc, s) => {
238	      acc[s.priority] = (acc[s.priority] || 0) + 1;
239	      return acc;
240	    },
241	    {} as Record<string, number>,
